/// <summary>
/// PaffH 25.02.21
/// </summary>
/// <remarks>
/// 1.0 : NDX/PaffH/NDX_TASK1235004494/29.09.2020 - get ProdBom with LineNum 1
/// </remarks>
/// <returns>
/// ProdBom with LineNum 1
/// </returns>
public ProdBOM NDXProdBomLine1()
{
    ProdBOM prodBom;
    ;
    select firstOnly * from prodBOM where prodBOM.ProdId == this.ProdId && prodBom.LineNum == 1;
    return prodBom;
}

/// <summary>
/// PaffH 02.03.21
/// </summary>
/// <remarks>
/// 1.0 : NDX/PaffH/NDX_TASK1235004494/29.09.2020 - get ProdRoute with OprNum 10 and OprPriority Secondary2
/// </remarks>
/// <returns>ProdRoute with OprNum 10 and OprPriority Secondary2</returns>
public ProdRoute NDXProdRouteOprNum10OprPrioritySec2()
{
    ProdRoute prodRoute;
    ;
    select firstOnly prodRoute 
        where prodRoute.ProdId == this.ProdId
            && prodRoute.OprNum == 10
            && prodRoute.OprPriority == RouteOprPriority::Secondary2;
    return prodRoute;
}

/// <summary>
/// PaffH 02.03.21
/// </summary>
/// <remarks>
/// 1.0 : NDX/PaffH/NDX_TASK1235004494/29.09.2020 - get ProdRoute with OprNum 10 and OprPriority Primary
/// </remarks>
/// <returns>ProdRoute with OprNum 10 and OprPriority Primary</returns>
public ProdRoute NDXProdRouteOprNum10OprPriorityPrim()
{
    ProdRoute prodRoute;
    ;
    select firstOnly prodRoute
        where prodRoute.ProdId == this.ProdId
        && prodRoute.OprNum == 10
        && prodRoute.OprPriority == RouteOprPriority::Primary;
    return prodRoute;
}

