/// <summary>
/// /// PaffH 01.03.21
/// get newest prodId from prodTable and number of prodTable records
/// </summary>
/// <returns>container</returns>
public static container NDXGetLastProdId()
{
    return [(select firstOnly ProdId from ProdTable order by ProdId desc).ProdId, (select count(RecId) from ProdTable).RecId];
}

/// <summary>
/// PaffH 03.03.21
/// </summary>
/// <param name = "_ProdTable">ProdTable</param>
/// <returns>str</returns>
//BP Deviation Documented
[SysClientCacheDataMethod]
public static display str TitleFields(ProdTable _ProdTable)
{
    return strFmt('%1-%2', _ProdTable.ProdId, _ProdTable.Name);
}
